"""
import json
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


class Client:
    def __init__(self, log_path, max_attempts=60):
        self.token = None
        self.log_path = log_path
        self.max_attempts = max_attempts
        self.tokens_issued = 0

    def _log(self, rec):
        rec["t"] = time.time()
        with open(self.log_path, "a") as f:
            f.write(json.dumps(rec) + "\n")

    def _raw(self, method, path, auth):
        """One HTTP attempt. Returns (status, headers dict, body bytes)."""
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", "Bearer " + self.token)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers or {}), e.read()

    @staticmethod
    def _retry_after(headers, body):
        """Wait time the service asked for, in seconds, or None."""
        for k, v in headers.items():
            if k.lower() == "retry-after":
                try:
                    return float(v)
                except ValueError:
                    pass
        try:
            d = json.loads(body)
        except Exception:
            return None
        if isinstance(d, dict):
            for k in ("retry_after", "retry_after_seconds", "wait", "wait_seconds"):
                if k in d:
                    return float(d[k])
            if "retry_after_ms" in d:
                return float(d["retry_after_ms"]) / 1000.0
        return None

    def request(self, method, path, auth=True, validate=None):
        """Perform a request until it succeeds, honouring the service's pushback.

        `validate(status, body_json)` may return an error string to force a retry
        on a response that looks successful but is unusable.
        Returns (status, parsed_json). A 404 is returned to the caller (not retried
        here) so the caller can decide whether it is genuine.
        """
        backoff = 0.5
        for attempt in range(1, self.max_attempts + 1):
            if auth and self.token is None:
                self.refresh_token()
            try:
                status, headers, body = self._raw(method, path, auth)
            except Exception as e:  # connection reset, timeout, etc.
                self._log({"path": path, "attempt": attempt, "exc": repr(e)})
                time.sleep(backoff)
                backoff = min(backoff * 2, 10)
                continue

            rec = {"path": path, "attempt": attempt, "status": status,
                   "token": self.token if auth else None}
            if status != 200:
                rec["headers"] = headers
                rec["body"] = body[:500].decode("utf-8", "replace")

            if status == 429:
                wait = self._retry_after(headers, body)
                rec["wait"] = wait
                self._log(rec)
                if wait is None:
                    wait = backoff
                    backoff = min(backoff * 2, 10)
                time.sleep(wait + 0.05)
                continue
            if status in (401, 403) and auth:
                self._log(rec)
                self.refresh_token()
                continue
            if status == 404:
                self._log(rec)
                try:
                    return status, json.loads(body)
                except Exception:
                    return status, None
            if status != 200:
                self._log(rec)
                wait = self._retry_after(headers, body)
                time.sleep(wait + 0.05 if wait is not None else backoff)
                backoff = min(backoff * 2, 10)
                continue

            try:
                data = json.loads(body)
            except Exception as e:
                rec["bad_json"] = repr(e)
                rec["body"] = body[:500].decode("utf-8", "replace")
                self._log(rec)
                time.sleep(backoff)
                backoff = min(backoff * 2, 10)
                continue
            if validate is not None:
                err = validate(status, data)
                if err:
                    rec["invalid"] = err
                    rec["body"] = body[:500].decode("utf-8", "replace")
                    self._log(rec)
                    time.sleep(backoff)
                    backoff = min(backoff * 2, 10)
                    continue
            self._log(rec)
            return status, data
        raise RuntimeError(f"giving up on {method} {path} after {self.max_attempts} attempts")

    def refresh_token(self):
        def ok(status, d):
            if not isinstance(d, dict) or not isinstance(d.get("token"), str) or not d["token"]:
                return "no token in response"
            return None
