"""Load a fetched order snapshot, de-duplicate it, and select qualifying orders."""
import glob
import json
import os
from datetime import datetime, timezone

RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)  # inclusive
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)    # exclusive (end of 31 May UTC)


def parse_utc(ts):
    dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        raise ValueError(f"timestamp without offset: {ts!r}")
    return dt.astimezone(timezone.utc)


def load_orders(run_dir):
    """Returns (unique orders in listing order, number of repeated listings discarded)."""
    pages = {}
    for p in glob.glob(os.path.join(run_dir, "page_*.json")):
        d = json.load(open(p))
        pages[d["page"]] = d
    total_pages = {d["total_pages"] for d in pages.values()}
    assert len(total_pages) == 1, total_pages
    assert sorted(pages) == list(range(1, total_pages.pop() + 1)), "missing pages"
    unique, dups = {}, 0
    for n in sorted(pages):
        for it in pages[n]["items"]:
            if it["id"] in unique:
                if unique[it["id"]] != it:
                    raise ValueError(f"conflicting duplicate listing for {it['id']}")
                dups += 1
                continue
            unique[it["id"]] = it
    return list(unique.values()), dups


def qualifying(orders):
    return [o for o in orders
            if o["status"] == "shipped"
            and RANGE_START <= parse_utc(o["placed_at"]) < RANGE_END]

